import{z as E,x as A,o as s,c as u,q as n,j as i,D as a,d as r,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Rust in kernel","description":"","frontmatter":{"title":"Rust in kernel","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rust-in-kernel.md","filePath":"cs/rust-in-kernel.md","lastUpdated":1791063341000}'),d={name:"cs/rust-in-kernel.md"};function c(B,e,p,h,_,f){const t=A("Mermaid");return s(),u("div",null,[e[2]||(e[2]=n('<h1 id="rust-in-kernel" tabindex="-1">Rust in kernel <a class="header-anchor" href="#rust-in-kernel" aria-label="Permalink to &quot;Rust in kernel&quot;">​</a></h1><div class="epigraph"><p>Linux 允许用 Rust 写部分驱动与子系统：借用检查在编译期排除一类空间错误，FFI 仍与 C 内核对话，panic 策略必须适合内核。</p><footer>—— 据 Linux Rust 文档；[ASan](/cs/asan-mechanism) 与 [MTE](/cs/memory-tagging) 为运行时对照；[kABI](/cs/kabi-module-signing) 为绑定</footer></div><p><a href="/cs/exokernel-libos">外核</a> 改架构。缺口是 <strong>在宏内核里换语言</strong>：Rust for Linux，不是用户态 tokio。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>C 驱动 UAF 是 CVE 大户。Rust 模块：安全子集 + <code>unsafe</code> 包 C API。缺口：bindings 生成；无标准堆 panic；与 <a href="/cs/livepatch">livepatch</a> 不成熟。本课不把所有 kernel crate 列出。<span class="marginnote">术语翻译：<code>unsafe</code> 块就是用「在类型系统里圈出一小块『免检区』、其余代码照常全检」的手段来做「底层操作照写、但风险被压缩到可人工审的小面积」的事——安全是默认值，例外要显式签字。</span></p><p><span class="marginnote">目标不是用 Rust 重写核心调度。对象是新驱动的记忆安全默认。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>kbuild 调 rustc → <code>.ko</code> 或内建。对照 <a href="/cs/asan-mechanism">KASAN</a>：动态 vs 静态。对照 seL4：证明 vs 类型。对照 <a href="/cs/chardev-ioctl">ioctl</a>：仍要定义 ABI。</p>',8)),(s(),i(l,null,{default:a(()=>[o(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RS%5B%22Rust%20%E9%A9%B1%E5%8A%A8%22%5D%20--%3E%20BIND%5B%22C%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20BIND%20--%3E%20CORE%5B%22C%20%E5%86%85%E6%A0%B8%E6%A0%B8%E5%BF%83%22%5D%0A%20%20RS%20--%3E%20CHK%5B%22%E5%80%9F%E7%94%A8%E6%A3%80%E6%9F%A5%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Rust in kernel 把一类内存安全从审查移到编译器，不消除逻辑 bug 与 <code>unsafe</code>。它改变新代码的默认质量。不要写成语言战争。与 <a href="/cs/secure-boot">Secure Boot</a>：模块仍要签名。与 <a href="/cs/ebpf-observability">eBPF</a>：BPF 已是另一条安全沙箱路径。<span class="marginnote">常见误区：初学者容易以为「内核用了 Rust 就安全了」——<code>unsafe</code> 块、DMA 缓冲区别名、逻辑死锁，类型系统统统不管；Rust 改变的是新代码里错误的默认分布，不是把正确性整个外包给编译器。</span></p>',2)),(s(),i(l,null,{default:a(()=>[o(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUG%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E6%82%AC%E7%A9%BA%E6%8C%87%E9%92%88%E9%94%99%E8%AF%AF%22%5D%20--%3E%20CPATH%5B%22C%20%E8%B7%AF%E5%BE%84%EF%BC%9A%E7%BC%96%E8%AF%91%E5%99%A8%E7%85%A7%E5%B8%B8%E6%94%BE%E8%A1%8C%22%5D%0A%20%20CPATH%20--%3E%20RUN%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%E8%B8%A9%E5%9D%8F%E5%88%AB%E4%BA%BA%E5%86%85%E5%AD%98%22%5D%0A%20%20RUN%20--%3E%20LATE%5B%22%E4%BA%8B%E5%90%8E%E9%9D%A0%E5%AE%A1%E6%9F%A5%20ASan%20%E6%88%96%20CVE%20%E5%8F%91%E7%8E%B0%22%5D%0A%20%20BUG%20--%3E%20RPATH%5B%22Rust%20%E8%B7%AF%E5%BE%84%EF%BC%9A%E5%80%9F%E7%94%A8%E6%A3%80%E6%9F%A5%E7%BC%96%E8%AF%91%E6%9C%9F%E6%8B%A6%E6%88%AA%22%5D%0A%20%20RPATH%20--%3E%20CAVEAT%5B%22unsafe%20%E5%9D%97%E9%99%A4%E5%A4%96%20%E4%BB%8D%E9%9C%80%E4%BA%BA%E5%B7%A5%E5%AE%A1%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=n('<p>工具链版本与内核树绑定是运维税。<span class="marginnote">数字实例：Android 团队报告过引入 Rust 后新内存安全漏洞占比明显下滑（约一半量级）——UAF、越界这类空间错误原本要等上线后变成 CVE，现在大多在 <code>cargo build</code> 那一秒就变成编译错误，发现成本差出几个数量级。</span></p><p>实现上：bindings 由脚本从 C 头生成，C 改布局就破。内核禁止普通 Rust 栈展开 panic。unsafe 块仍要人工审，类型系统不审 DMA 别名。 读法上只引用<a href="/cs/exokernel-libos">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「虚拟化与隔离进阶 / 容器与内核形态」课序里，对象是 <strong>Rust in kernel</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 <code>unsafe</code> 指南。不保证实时路径用 Rust。下一课对照另一宏内核：Windows NT。</p><p>版本字段会变，课序钉的是机制对象「Rust in kernel」，不是某一主线内核的结构体名。 后课默认：新驱动可用 Rust 绑进 Linux。NT 内核对象模型对照，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Rust 模块用类型系统减空间错误，经 FFI 调 C。</li><li>不替换整个内核；panic 与分配器要特化。</li><li>Windows NT 对照是下一课。</li><li>出处：Linux rust；kbuild；内存安全课先修。</li></ul>',9))])}const k=E(d,[["render",c]]);export{C as __pageData,k as default};
